changeSet.sql:
do $drop$
declare
    missing integer := 0;
begin
    if exists (select 1 from enterprise_identity_connections where status = 'ACTIVE') then
        if to_regclass('idn_entity') is null or to_regclass('idn_login_connection') is null then
            raise exception 'OLD_SIGN_IN_CONNECTION_NOT_CARRIED_OVER: run the schema step, setup and the identity migration first';
        end if;
        select count(*) into missing
          from enterprise_identity_connections old
          join idn_entity e on e.entity_uuid = old.tenant_id
         where old.status = 'ACTIVE'
           and not exists (select 1 from idn_login_connection c
                            where c.tenant_id = e.tenant_id and c.product_code = 'LEXAVAULT'
                              and c.status = 'ACTIVE');
        if missing > 0 then
            raise exception 'OLD_SIGN_IN_CONNECTION_NOT_CARRIED_OVER: % connection(s); run the identity migration of the release before this one, or setup, first', missing;
        end if;
    end if;
    drop table enterprise_identity_connections;
end $drop$;
